fi

# --- LLM gating: web_extract.py and the SKILL "LLM extraction" section ship only with an LLM
echo
echo "===== LLM gating: scripts and skill section follow the LLM choice ====="
llm_scenario() {  # llm_scenario LABEL HOMEDIR TARGET EXPECT_LLM(yes|no) EXPECT_ACCOUNT(yes|no); answers on stdin
  local label="$1" h="$2" t="$3" want="$4" acct="$5"
  mkdir -p "$h"
  env HOME="$h" PATH="$MOCKBIN:$PATH" "$SRC_DIR/install-local-search.sh" > "$TESTROOT/llm-$label.log" 2>&1
  local rc=$? sd="$h/.agents/skills/local-web-search" ok=1
  [ "$rc" = 0 ] || { echo "  [FAIL] $label: installer exit code $rc"; ok=0; }
  for d in "$t/local-web-search" "$sd"; do
    if [ "$want" = yes ]; then
      [ -s "$d/scripts/web_extract.py" ] && grep -q "^## LLM extraction" "$d/SKILL.md" \
        || { echo "  [FAIL] $label: web_extract.py / LLM section missing in $d"; ok=0; }
    else
      [ ! -e "$d/scripts/web_extract.py" ] && ! grep -qi "LLM" "$d/SKILL.md" \
        || { echo "  [FAIL] $label: LLM extraction present in $d without an LLM"; ok=0; }
    fi
    [ ! -e "$d/SKILL-llm.md" ] && [ ! -e "$d/SKILL-core.md" ] \
      || { echo "  [FAIL] $label: build-time SKILL variant leaked into $d"; ok=0; }
    if [ "$acct" = yes ]; then
      [ -s "$d/scripts/web_monitor_create.py" ] || { echo "  [FAIL] $label: account tools missing in $d"; ok=0; }
    else
      [ ! -e "$d/scripts/web_monitor_create.py" ] || { echo "  [FAIL] $label: account tools present in $d"; ok=0; }
    fi
  done
  if [ "$ok" = 1 ]; then echo "  [OK]   $label"; else tail -15 "$TESTROOT/llm-$label.log"; PASS=0; fi
}
# setup 2 with explicit endpoint, key and model
llm_scenario opt2 "$TESTROOT/home-opt2" "$TESTROOT/home-opt2/local-search" yes no < <(printf '%s\n' 2 "http://localhost:8080/v1" "sk-e2e-key" "my-model" "y")
