else
  echo "[FAIL] uninstaller deleted the install folder despite 'n'"
  PASS=0
fi

echo
if [ "$PASS" = 1 ]; then
  echo "========================  ALL TESTS PASSED  ========================"
  exit 0
fi
echo "========================  TESTS FAILED  ==========================="
exit 1
EOF_E2E_TEST_SH

# --- zip_test.sh ---
cat > "$TARGET/zip_test.sh" <<'EOF_ZIP_TEST_SH'
#!/usr/bin/env bash
# Verify local-search.zip: extract it into a clean temp dir, run the .sh
# installer FROM the extracted folder (all sources present), and check the
# result (incl. the local-web-search skill). Needs: unzip + python3.
# Any pre-existing ~/.agents/skills/local-web-search is backed up and restored.
set -u

ROOT="$(cd "$(dirname "$0")" && pwd)"
ZIP="$ROOT/local-search.zip"
TESTROOT="$ROOT/.zip-test-$$"
SKILL_DIR="$HOME/.agents/skills/local-web-search"
SKILL_BAK=""

PY="$(command -v python3 || command -v python)"
[ -z "$PY" ] && { echo "[ERROR] python required for this test." >&2; exit 1; }

cleanup() {
  rc=$?
  rm -rf "$SKILL_DIR" 2>/dev/null
  if [ -n "$SKILL_BAK" ] && [ -d "$SKILL_BAK" ]; then
    mv "$SKILL_BAK" "$SKILL_DIR" 2>/dev/null
  fi
  if [ "$rc" = 0 ]; then rm -rf "$TESTROOT"; fi
}
trap cleanup EXIT

[ -f "$ZIP" ] || { echo "[ERROR] $ZIP not found - run build.sh first." >&2; exit 1; }
command -v unzip >/dev/null 2>&1 || { echo "[ERROR] unzip not found." >&2; exit 1; }

mkdir -p "$TESTROOT"
cd "$TESTROOT"
unzip -q "$ZIP"
echo "Extracted zip contents:"
find local-search -type f | sort
echo

# Back up any real skill install so the test can never destroy it.
if [ -d "$SKILL_DIR" ]; then
  SKILL_BAK="$TESTROOT/skill-backup"
  mv "$SKILL_DIR" "$SKILL_BAK"
fi

# --- mock docker so the installer's checks pass ----------------------------
MOCKBIN="$TESTROOT/bin"
mkdir -p "$MOCKBIN"
cat > "$MOCKBIN/docker" <<'MOCK'
#!/usr/bin/env bash
case "$1" in
  info)  exit 0 ;;
  compose)
    case "$2" in
      version) echo "Docker Compose v2.0.0-test"; exit 0 ;;
      pull|up) echo "[mock] ok"; exit 0 ;;
      *) exit 0 ;;
    esac ;;
  *) exit 0 ;;
esac
MOCK
chmod +x "$MOCKBIN/docker"
export PATH="$MOCKBIN:$PATH"

# --- run the installer from the extracted folder (full source present) ------
# answers: setup type 3, target, searxng port, firecrawl port, browserless? -> n (playwright),
#          LLM? -> n, Firecrawl account? -> n (core-only default), confirm -> y
TGT="$TESTROOT/installed"
printf '%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n' "3" "$TGT" "" "" "n" "n" "n" "y" \
  | "$TESTROOT/local-search/install-local-search.sh" > "$TESTROOT/install.log" 2>&1
RC=$?
echo "Installer exit code: $RC"
tail -10 "$TESTROOT/install.log"
echo "=========================================="

# --- verify the install folder ----------------------------------------------
PASS=1
for f in docker-compose.yml .env.example .env README.md LICENSE .gitignore .gitattributes \
         config/searxng/settings.yml \
         Run.bat Stop.bat Update.bat Uninstall.bat \
         run.sh stop.sh update.sh uninstall.sh \
         local-web-search/SKILL.md \
         local-web-search/scripts/config.py local-web-search/scripts/ensure_stack.py \
         local-web-search/scripts/web_search.py local-web-search/scripts/web_scrape.py \
         local-web-search/scripts/web_youtube_transcript.py \
         install-local-search.bat install-local-search.sh; do
  if [ -s "$TGT/$f" ]; then
    echo "  [OK] $f"
  else
    echo "  [FAIL] $f (missing/empty)"; PASS=0
  fi
done

if grep -q '__SEARXNG_SECRET_PLACEHOLDER__' "$TGT/config/searxng/settings.yml"; then
  echo "[FAIL] settings.yml still has placeholder"; PASS=0
else
  echo "[OK] settings.yml secret injected"
fi

# core-only default: no account-gated tools, core SKILL.md, no leaked variant
if [ -e "$TGT/local-web-search/scripts/web_agent.py" ] \
   || [ -e "$TGT/local-web-search/scripts/web_monitor_create.py" ] \
   || [ -e "$TGT/local-web-search/scripts/web_extract.py" ] \
   || [ -e "$TGT/local-web-search/SKILL-core.md" ] \
   || [ -e "$TGT/local-web-search/SKILL-llm.md" ]; then
  echo "[FAIL] account-gated or LLM tools (or a SKILL variant) installed in core mode without an LLM"; PASS=0
else
  echo "[OK] core-only skill: account-gated and LLM tools skipped, no SKILL variants left"
fi
if grep -qF "Tools: search, scrape, map, crawl, crawl status, YouTube transcripts." "$TGT/local-web-search/SKILL.md"; then
  echo "[OK] SKILL.md is the core-only variant"
else
  echo "[FAIL] SKILL.md is not the core-only variant"; PASS=0
fi

if [ "$(cat "$SKILL_DIR/install-dir.txt" 2>/dev/null)" = "$TGT" ]; then
  echo "[OK] skill installed with correct install-dir.txt hint"
else
  echo "[FAIL] skill install-dir.txt wrong: $(cat "$SKILL_DIR/install-dir.txt" 2>/dev/null)"
  PASS=0
fi

cmp -s "$TGT/install-local-search.bat" "$ROOT/local-search/install-local-search.bat" \
  && echo "[OK] .bat reproduced byte-identical" \
  || { echo "[FAIL] .bat differs"; PASS=0; }

echo
if [ "$PASS" = 1 ] && [ "$RC" = 0 ]; then
  echo "======== FULL-ZIP EXTRACTION TEST: PASSED ========"
  exit 0
fi
echo "======== FULL-ZIP EXTRACTION TEST: FAILED ========"
exit 1
EOF_ZIP_TEST_SH

# --- selfhost_test.sh ---
cat > "$TARGET/selfhost_test.sh" <<'EOF_SELFHOST_TEST_SH'
#!/usr/bin/env bash
# Self-hosting test for the rig packers:
#   1. Run local-search-rig.sh into a clean folder (only the packer present).
#   2. Verify the unpacked rig is complete and byte-identical to the source.
#   3. Regenerate the packers inside the unpacked rig (python3 gen_rig.py)
#      and compare them BYTE-FOR-BYTE with the originals.
#   4. Regenerate the installers too and compare.
set -u
ROOT="$(cd "$(dirname "$0")" && pwd)"
TESTROOT="$ROOT/.rig-test-$$"
mkdir -p "$TESTROOT"

cleanup() { rc=$?; if [ "$rc" = 0 ]; then rm -rf "$TESTROOT"; else echo "(kept $TESTROOT for debugging)"; fi; }
trap cleanup EXIT

echo "=== 1. unpack local-search-rig.sh (only the packer file present) ==="
mkdir -p "$TESTROOT/src"
cp "$ROOT/local-search-rig.sh" "$TESTROOT/src/"
chmod +x "$TESTROOT/src/local-search-rig.sh"
# answers: target folder, build now? -> n (we build manually later), proceed -> y
printf '%s\n%s\n%s\n' "$TESTROOT/rig" "n" "y" \
  | "$TESTROOT/src/local-search-rig.sh" > "$TESTROOT/unpack.log" 2>&1
RC=$?
echo "packer exit code: $RC"
tail -8 "$TESTROOT/unpack.log"
[ "$RC" = 0 ] || exit 1
echo

echo "=== 2. unpacked rig contents ==="
find "$TESTROOT/rig" -type f | sort
echo

PASS=1
echo "=== 3. byte-compare unpacked rig vs source rig ==="

check_file() {
  if [ ! -f "$TESTROOT/rig/$1" ]; then
    echo "  [FAIL] missing in unpacked rig: $1"; PASS=0; return
  fi
  if cmp -s "$ROOT/$1" "$TESTROOT/rig/$1"; then
    echo "  [OK]   $1"
  else
    # .bat files are allowed CRLF<->LF differences only if LF-normalised equal
    a=$(tr -d '\r' < "$ROOT/$1" | md5sum | cut -d' ' -f1)
    b=$(tr -d '\r' < "$TESTROOT/rig/$1" | md5sum | cut -d' ' -f1)
    if [ "$a" = "$b" ] && [ "$(md5sum < "$ROOT/$1" | cut -d' ' -f1)" != "$a" ]; then
      echo "  [OK]   $1  (CRLF restored)"
    else
      echo "  [FAIL] $1 differs"; PASS=0
    fi
  fi
}

for f in config/searxng/settings.yml docker-compose.yml .env.example README.md \
         LICENSE .gitignore .gitattributes \
         Run.bat Stop.bat Update.bat Uninstall.bat \
         run.sh stop.sh update.sh uninstall.sh \
         local-web-search/SKILL.md local-web-search/SKILL-core.md local-web-search/SKILL-llm.md \
         local-web-search/scripts/config.py local-web-search/scripts/ensure_stack.py \
         local-web-search/scripts/web_search.py local-web-search/scripts/web_scrape.py local-web-search/scripts/web_extract.py \
         local-web-search/scripts/web_youtube_transcript.py; do
  check_file "local-search/$f"
done
# NOTE: local-search/install-local-search.* are intentionally NOT unpacked by
# the packer (they are generated artifacts) - they are verified in step 5.

for f in gen_installers.py gen_rig.py test_b64.py test_heredocs.py test_rig.py \
         e2e_test.sh zip_test.sh selfhost_test.sh build.sh build.bat BUILD.md \
         e2e_test.bat zip_test.bat selfhost_test.bat e2e_check.py \
         mock_docker.cs mock_docker_build.bat \
         local-search-rig.bat local-search-rig.sh; do
  check_file "$f"
done

# .bat files unpacked by the .sh packer must have CRLF endings
for f in local-search/Run.bat local-search/Update.bat local-search-rig.bat build.bat \
         e2e_test.bat zip_test.bat selfhost_test.bat mock_docker_build.bat; do
  if grep -q $'\r' "$TESTROOT/rig/$f" 2>/dev/null; then
    echo "  [OK]   $f has CRLF"
  else
    echo "  [FAIL] $f lacks CRLF"; PASS=0
  fi
done
echo

echo "=== 4. SELF-HOSTING: regenerate packers inside unpacked rig ==="
if (cd "$TESTROOT/rig" && python3 gen_rig.py); then
  if cmp -s "$ROOT/local-search-rig.sh" "$TESTROOT/rig/local-search-rig.sh"; then
    echo "  [OK] local-search-rig.sh regenerated BYTE-IDENTICAL"
  else
    echo "  [FAIL] local-search-rig.sh differs after regeneration"; PASS=0
  fi
  if cmp -s "$ROOT/local-search-rig.bat" "$TESTROOT/rig/local-search-rig.bat"; then
    echo "  [OK] local-search-rig.bat regenerated BYTE-IDENTICAL"
  else
    echo "  [FAIL] local-search-rig.bat differs after regeneration"; PASS=0
  fi
else
  echo "  [FAIL] gen_rig.py failed in unpacked rig"; PASS=0
fi
echo

echo "=== 5. regenerate installers inside unpacked rig ==="
if (cd "$TESTROOT/rig" && python3 gen_installers.py); then
  if cmp -s "$ROOT/local-search/install-local-search.sh" "$TESTROOT/rig/local-search/install-local-search.sh"; then
    echo "  [OK] install-local-search.sh regenerated BYTE-IDENTICAL"
  else
    echo "  [FAIL] install-local-search.sh differs"; PASS=0
  fi
  if cmp -s "$ROOT/local-search/install-local-search.bat" "$TESTROOT/rig/local-search/install-local-search.bat"; then
    echo "  [OK] install-local-search.bat regenerated BYTE-IDENTICAL"
  else
    echo "  [FAIL] install-local-search.bat differs"; PASS=0
  fi
else
  echo "  [FAIL] gen_installers.py failed in unpacked rig"; PASS=0
fi
echo

echo "=== 6. verify test suite passes inside the unpacked rig ==="
if (cd "$TESTROOT/rig" && python3 test_rig.py > /dev/null 2>&1); then
  echo "  [OK] test_rig.py passes in unpacked rig"
else
  echo "  [FAIL] test_rig.py fails in unpacked rig"; PASS=0
fi

echo
if [ "$PASS" = 1 ]; then
  echo "=================  SELF-HOSTING TEST: PASSED  ================="
  exit 0
fi
echo "=================  SELF-HOSTING TEST: FAILED  ================="
exit 1
EOF_SELFHOST_TEST_SH

# --- build.sh ---
cat > "$TARGET/build.sh" <<'EOF_BUILD_SH'
#!/usr/bin/env bash
# Build + test everything in the local-search dev rig.
#   1. regenerate the two installers        (gen_installers.py)
#   2. syntax-check + verify embedded files (test_b64.py / test_heredocs.py)
#   3. full install/uninstall e2e test      (e2e_test.sh, mocked docker)
#   4. regenerate the rig packers           (gen_rig.py) + verify (test_rig.py)
#   5. build local-search.zip               (+ zip_test.sh when unzip exists)
set -u
cd "$(dirname "$0")" || exit 1

PY="$(command -v python3 || command -v python)"
if [ -z "$PY" ]; then
  echo "[ERROR] python3 (or python) not found on PATH." >&2
  exit 1
fi

echo "== [1/6] Generating installers (gen_installers.py) =="
"$PY" gen_installers.py || exit 1

echo "== [2/6] bash syntax check =="
bash -n local-search/install-local-search.sh || {
  echo "[FAIL] install-local-search.sh has bash syntax errors" >&2; exit 1; }
echo "  syntax OK"

echo "== [3/6] Embedded-file tests =="
"$PY" test_b64.py || exit 1
"$PY" test_heredocs.py || exit 1

echo "== [4/6] End-to-end install test (mocked docker) =="
bash e2e_test.sh || exit 1

echo "== [5/6] Regenerating rig packers (gen_rig.py) =="
"$PY" gen_rig.py || exit 1
"$PY" test_rig.py || exit 1
if bash selfhost_test.sh; then :; else
  echo "[FAIL] self-hosting test failed" >&2; exit 1
fi

echo "== [6/6] Building local-search.zip =="
rm -f local-search.zip
if command -v zip >/dev/null 2>&1; then
  zip -r local-search.zip local-search/ -x 'local-search/.git/*' '*/__pycache__/*' > /dev/null || exit 1
  echo "  local-search.zip built."
  if command -v unzip >/dev/null 2>&1; then
    bash zip_test.sh || exit 1
  fi
else
  echo "  [WARNING] 'zip' not found - skipping zip (installers are unaffected)."
fi

echo
echo "ALL GREEN. Artifacts:"
echo "  local-search/install-local-search.bat / .sh   <- the installers"
echo "  local-search-rig.bat / local-search-rig.sh    <- the dev-rig packers"
echo "  local-search.zip                              <- repo snapshot for GitHub"
EOF_BUILD_SH

# --- e2e_test.bat ---
cat > "$TARGET/e2e_test.bat" <<'EOF_E2E_TEST_BAT'
@echo off
setlocal enableDelayedExpansion
title Local Search Dev Rig - End-to-end test (Windows)
REM ===========================================================================
REM  End-to-end test of install-local-search.bat / Uninstall.bat on Windows
REM  (analog of e2e_test.sh).
REM
REM    * simulates downloading ONLY the installer (nothing else next to it)
REM    * puts a compiled mock docker.exe first on PATH (mock_docker.cs), so the
REM      real install logic runs without touching a Docker daemon
REM    * runs with USERPROFILE redirected into the test folder, so a real
REM      user-profile skill folder (.agents\skills\local-web-search) is never touched
REM    * drives every prompt by PIPING scripted answers into the installers
REM      (script.bat with stdin redirected from an answers file). Answers are deliberately NOT the defaults
REM      (ports 9980/9981, a custom target) so an installer that ignores piped
REM      stdin falls back to defaults and fails here.
REM
REM  Scenarios: core install (run from a console left on code page 65001),
REM  quick-setup install, account-mode install, uninstall keeping the folder,
REM  uninstall deleting it. All assertions live in e2e_check.py.
REM  Test folders are removed on success and kept on failure for debugging.
REM ===========================================================================

cd /d "%~dp0"
set "ROOT=%CD%"

set "PY="
py -3 -c "print(1)" >nul 2>&1
if not errorlevel 1 set "PY=py -3"
if not defined PY (
  python -c "print(1)" >nul 2>&1
  if not errorlevel 1 set "PY=python"
)
if not defined PY (
  python3 -c "print(1)" >nul 2>&1
  if not errorlevel 1 set "PY=python3"
)
if not defined PY (
  echo [ERROR] Python not found ^(py / python / python3^).
  exit /b 1
)

set "INSTALLER=%ROOT%\local-search\install-local-search.bat"
if not exist "%INSTALLER%" (
  echo [ERROR] !INSTALLER! not found - run build.bat or python gen_installers.py first.
  exit /b 1
)

set "TESTROOT=%ROOT%\.ls-test-%RANDOM%"
set "SRC_DIR=%TESTROOT%\src-only-installer"
set "MOCKBIN=%TESTROOT%\bin"
mkdir "%SRC_DIR%" "%MOCKBIN%" >nul 2>&1
set "PASS=1"

echo ===== building the mock docker.exe =====
call "%ROOT%\mock_docker_build.bat" "%MOCKBIN%"
if errorlevel 1 (
  echo [FAIL] could not build the mock docker.exe
  exit /b 1
)
set "MOCK_DOCKER_LOG=%TESTROOT%\docker-calls.log"
set "PATH=%MOCKBIN%;%PATH%"

REM Safety: the FIRST docker on PATH must be the mock, never a real Docker.
set "FIRSTDOCKER="
for /f "delims=" %%w in ('where docker 2^>nul') do if not defined FIRSTDOCKER set "FIRSTDOCKER=%%w"
if /i not "!FIRSTDOCKER!"=="%MOCKBIN%\docker.exe" (
  echo [FAIL] the mock docker is not first on PATH ^(found: !FIRSTDOCKER!^) - aborting for safety.
  exit /b 1
)
echo   mock docker OK: !FIRSTDOCKER!

REM --- copy ONLY the installer into the source folder ------------------------
copy /Y "%INSTALLER%" "%SRC_DIR%\" >nul
echo Source folder contents ^(should be ONLY install-local-search.bat^):
dir /b "%SRC_DIR%"
echo.

REM ===========================================================================
REM  1. CORE install, custom answers, console deliberately left on code page 65001
REM ===========================================================================
echo ===== 1. core install: scripted NON-default answers piped into the installer =====
set "T1=%TESTROOT%\target-core"
set "H1=%TESTROOT%\home-core"
mkdir "!H1!" >nul 2>&1
set "USERPROFILE=!H1!"
REM   answers in order: setup type 3 (full), target, SearXNG port, Firecrawl port,
REM   browserless? n, LLM? n, Firecrawl account? n, proceed? y
(
  echo 3
  echo !T1!
  echo 9980
  echo 9981
  echo n
  echo n
  echo n
  echo y
) > "%TESTROOT%\ans-core.txt"
chcp 65001 >nul
call :run_bat "%SRC_DIR%\install-local-search.bat" "%TESTROOT%\ans-core.txt" "%TESTROOT%\install-core.log"
call :show_tail "%TESTROOT%\install-core.log"
%PY% "%ROOT%\e2e_check.py" install --target "!T1!" --home "!H1!" --mode core --platform windows --searxng-port 9980 --firecrawl-port 9981
if errorlevel 1 set "PASS=0"
%PY% "%ROOT%\e2e_check.py" docker-log "%MOCK_DOCKER_LOG%" "compose pull" "compose up -d"
if errorlevel 1 set "PASS=0"

REM ===========================================================================
REM  2. MINIMAL install: setup type 1 asks nothing else; Enter confirms
REM ===========================================================================
echo.
echo ===== 2. minimal install: setup type 1 =====
set "H2=%TESTROOT%\home-quick"
mkdir "!H2!" >nul 2>&1
set "USERPROFILE=!H2!"
(
  echo 1
  echo.
) > "%TESTROOT%\ans-quick.txt"
call :run_bat "%SRC_DIR%\install-local-search.bat" "%TESTROOT%\ans-quick.txt" "%TESTROOT%\install-quick.log"
call :show_tail "%TESTROOT%\install-quick.log"
%PY% "%ROOT%\e2e_check.py" install --target "!H2!\local-search" --home "!H2!" --mode core --platform windows --searxng-port 9990 --firecrawl-port 9991
if errorlevel 1 set "PASS=0"

REM ===========================================================================
REM  3. ACCOUNT-mode install: fake Firecrawl account, every tool script installs
REM ===========================================================================
echo.
echo ===== 3. account-mode install: fake Firecrawl account =====
set "T3=%TESTROOT%\target-account"
set "H3=%TESTROOT%\home-account"
mkdir "!H3!" >nul 2>&1
set "USERPROFILE=!H3!"
REM   answers in order: setup type 3, target, both ports (Enter = default), browserless? n,
REM   LLM? n, account? y, API key, API URL (Enter = default), proceed? y
(
  echo 3
  echo !T3!
  echo.
  echo.
  echo n
  echo n
  echo y
  echo fc-e2e-test-key-123
  echo.
  echo y
) > "%TESTROOT%\ans-account.txt"
call :run_bat "%SRC_DIR%\install-local-search.bat" "%TESTROOT%\ans-account.txt" "%TESTROOT%\install-account.log"
call :show_tail "%TESTROOT%\install-account.log"
%PY% "%ROOT%\e2e_check.py" install --target "!T3!" --home "!H3!" --mode account --platform windows --searxng-port 9990 --firecrawl-port 9991 --api-key fc-e2e-test-key-123
if errorlevel 1 set "PASS=0"

REM ===========================================================================
REM  3b-3d. LLM gating: web_extract.py and the skill's LLM extraction section
REM  are installed only when an LLM is connected.
REM ===========================================================================
echo.
echo ===== 3b. setup 2: explicit LLM endpoint, key and model =====
set "H4=%TESTROOT%\home-opt1"
mkdir "!H4!" >nul 2>&1
set "USERPROFILE=!H4!"
(
  echo 2
  echo http://localhost:8080/v1
  echo sk-e2e-key
  echo my-model
  echo y
) > "%TESTROOT%\ans-opt1.txt"
call :run_bat "%SRC_DIR%\install-local-search.bat" "%TESTROOT%\ans-opt1.txt" "%TESTROOT%\install-opt1.log"
call :show_tail "%TESTROOT%\install-opt1.log"
%PY% "%ROOT%\e2e_check.py" install --target "!H4!\local-search" --home "!H4!" --mode core --platform windows --llm yes --llm-url http://host.docker.internal:8080/v1 --llm-key sk-e2e-key --llm-model my-model
if errorlevel 1 set "PASS=0"

echo.
echo ===== 3c. Enter at the setup prompt selects setup 1: minimal, no LLM =====
set "H5=%TESTROOT%\home-enter"
mkdir "!H5!" >nul 2>&1
set "USERPROFILE=!H5!"
(
  echo.
) > "%TESTROOT%\ans-enter.txt"
call :run_bat "%SRC_DIR%\install-local-search.bat" "%TESTROOT%\ans-enter.txt" "%TESTROOT%\install-enter.log"
call :show_tail "%TESTROOT%\install-enter.log"
%PY% "%ROOT%\e2e_check.py" install --target "!H5!\local-search" --home "!H5!" --mode core --platform windows --llm no
if errorlevel 1 set "PASS=0"

echo.
echo ===== 3d. setup 3: LLM answered y with default endpoint, plus a Firecrawl account =====
set "T6=%TESTROOT%\target-all"
set "H6=%TESTROOT%\home-all"
mkdir "!H6!" >nul 2>&1
set "USERPROFILE=!H6!"
REM   answers in order: setup type 3, target, both ports, browserless? n, connect LLM? y,
REM   base URL / key / model Enter, account? y, API key, API URL Enter, proceed? y
(
  echo 3
  echo !T6!
  echo.
  echo.
  echo n
  echo y
  echo.
  echo.
  echo.
  echo y
  echo fc-llm-key
  echo.
  echo y
) > "%TESTROOT%\ans-all.txt"
call :run_bat "%SRC_DIR%\install-local-search.bat" "%TESTROOT%\ans-all.txt" "%TESTROOT%\install-all.log"
call :show_tail "%TESTROOT%\install-all.log"
%PY% "%ROOT%\e2e_check.py" install --target "!T6!" --home "!H6!" --mode account --platform windows --llm yes --api-key fc-llm-key
if errorlevel 1 set "PASS=0"

REM ===========================================================================
REM  4. UNINSTALL (core install): confirm y, keep the folder n
REM ===========================================================================
echo.
echo ===== 4. Uninstall.bat: answers y then n (keep the folder) =====
set "USERPROFILE=!H1!"
(
  echo y
  echo n
) > "%TESTROOT%\ans-un1.txt"
call :run_bat "!T1!\Uninstall.bat" "%TESTROOT%\ans-un1.txt" "%TESTROOT%\uninstall-core.log"
call :show_tail "%TESTROOT%\uninstall-core.log"
%PY% "%ROOT%\e2e_check.py" uninstall --target "!T1!" --home "!H1!" --folder kept
if errorlevel 1 set "PASS=0"
%PY% "%ROOT%\e2e_check.py" docker-log "%MOCK_DOCKER_LOG%" "compose down"
if errorlevel 1 set "PASS=0"

REM ===========================================================================
REM  5. UNINSTALL (account install): confirm y, delete the folder y
REM     The second prompt comes AFTER the work, so this also proves the prompt
REM     still reads piped input after the UTF-8 switch for the docker output.
REM ===========================================================================
echo.
echo ===== 5. Uninstall.bat: answers y then y (delete the folder) =====
set "USERPROFILE=!H3!"
(
  echo y
  echo y
) > "%TESTROOT%\ans-un2.txt"
call :run_bat "!T3!\Uninstall.bat" "%TESTROOT%\ans-un2.txt" "%TESTROOT%\uninstall-account.log" ignorerc
call :show_tail "%TESTROOT%\uninstall-account.log"
%PY% "%ROOT%\e2e_check.py" uninstall --target "!T3!" --home "!H3!" --folder removed
if errorlevel 1 set "PASS=0"

echo.
cd /d "%ROOT%"
if "!PASS!"=="1" (
  echo ========================  ALL TESTS PASSED  ========================
  rd /s /q "%TESTROOT%" >nul 2>&1
  exit /b 0
)
echo ========================  TESTS FAILED  ===========================
echo   Test folder kept for debugging: %TESTROOT%
exit /b 1

REM ---------------------------------------------------------------------------
REM  :run_bat script answers-file log-file [ignorerc]
REM  Runs the script with the answers file redirected into its stdin. CALL is
REM  mandatory: a .bat started without it never returns to this test. The
REM  optional 4th argument skips the exit-code check (Uninstall.bat deletes its
REM  own folder while running, so its exit code is not meaningful there).
REM ---------------------------------------------------------------------------
:run_bat
call "%~1" < "%~2" > "%~3" 2>&1
set "RC=!errorlevel!"
cd /d "%ROOT%"
echo   exit code of %~nx1: !RC!
if /i "%~4"=="ignorerc" goto :eof
if not "!RC!"=="0" (
  echo   [FAIL] %~nx1 exited with !RC!
  set "PASS=0"
)
goto :eof

:show_tail
echo ----- %~nx1 -----
type "%~1"
echo -------------------------------
goto :eof
EOF_E2E_TEST_BAT

# --- zip_test.bat ---
cat > "$TARGET/zip_test.bat" <<'EOF_ZIP_TEST_BAT'
@echo off
setlocal enableDelayedExpansion
title Local Search Dev Rig - Zip extraction test (Windows)
REM ===========================================================================
REM  Verify local-search.zip on Windows (analog of zip_test.sh): extract it into
REM  a clean temp folder, run install-local-search.bat FROM the extracted folder
REM  (all sources present next to it), piping scripted answers into it, and
REM  check the result with e2e_check.py. Uses the compiled mock docker.exe and a
REM  USERPROFILE redirected into the test folder, so nothing real is touched.
REM  Needs: tar.exe or PowerShell (both ship with Windows 10/11) and Python.
REM ===========================================================================

cd /d "%~dp0"
set "ROOT=%CD%"
set "ZIP=%ROOT%\local-search.zip"

set "PY="
py -3 -c "print(1)" >nul 2>&1
if not errorlevel 1 set "PY=py -3"
if not defined PY (
  python -c "print(1)" >nul 2>&1
  if not errorlevel 1 set "PY=python"
)
if not defined PY (
  python3 -c "print(1)" >nul 2>&1
  if not errorlevel 1 set "PY=python3"
)
if not defined PY (
  echo [ERROR] Python not found ^(py / python / python3^).
  exit /b 1
)

if not exist "%ZIP%" (
  echo [ERROR] !ZIP! not found - run build.bat first.
  exit /b 1
)

set "TESTROOT=%ROOT%\.zip-test-%RANDOM%"
set "MOCKBIN=%TESTROOT%\bin"
set "HOMEDIR=%TESTROOT%\home"
set "TGT=%TESTROOT%\installed"
mkdir "%TESTROOT%" "%MOCKBIN%" "%HOMEDIR%" >nul 2>&1
set "PASS=1"

echo ===== extracting local-search.zip =====
tar -xf "%ZIP%" -C "%TESTROOT%" >nul 2>&1
if not exist "%TESTROOT%\local-search\install-local-search.bat" (
  powershell -NoProfile -Command "Expand-Archive -LiteralPath '%ZIP%' -DestinationPath '%TESTROOT%' -Force" >nul 2>&1
)
if not exist "%TESTROOT%\local-search\install-local-search.bat" (
  echo [FAIL] could not extract the zip ^(no install-local-search.bat inside local-search\^)
  exit /b 1
)
echo   extracted to %TESTROOT%\local-search

echo ===== building the mock docker.exe =====
call "%ROOT%\mock_docker_build.bat" "%MOCKBIN%"
if errorlevel 1 (
  echo [FAIL] could not build the mock docker.exe
  exit /b 1
)
set "MOCK_DOCKER_LOG=%TESTROOT%\docker-calls.log"
set "PATH=%MOCKBIN%;%PATH%"
set "USERPROFILE=%HOMEDIR%"

REM Safety: the FIRST docker on PATH must be the mock, never a real Docker.
set "FIRSTDOCKER="
for /f "delims=" %%w in ('where docker 2^>nul') do if not defined FIRSTDOCKER set "FIRSTDOCKER=%%w"
if /i not "!FIRSTDOCKER!"=="%MOCKBIN%\docker.exe" (
  echo [FAIL] the mock docker is not first on PATH ^(found: !FIRSTDOCKER!^) - aborting for safety.
  exit /b 1
)

echo ===== installing from the extracted folder =====
REM   answers in order: setup type 3, target, both ports (Enter = default),
REM   browserless? n, LLM? n, Firecrawl account? n, proceed? y
(
  echo 3
  echo !TGT!
  echo.
  echo.
  echo n
  echo n
  echo n
  echo y
) > "%TESTROOT%\answers.txt"
call "%TESTROOT%\local-search\install-local-search.bat" < "%TESTROOT%\answers.txt" > "%TESTROOT%\install.log" 2>&1
set "RC=!errorlevel!"
cd /d "%ROOT%"
echo   installer exit code: !RC!
type "%TESTROOT%\install.log"
echo ==========================================
if not "!RC!"=="0" set "PASS=0"

%PY% "%ROOT%\e2e_check.py" install --target "!TGT!" --home "!HOMEDIR!" --mode core --platform windows
if errorlevel 1 set "PASS=0"

REM The installer copies itself into the target: it must be byte-identical.
%PY% "%ROOT%\e2e_check.py" same "%ROOT%\local-search\install-local-search.bat" "!TGT!\install-local-search.bat"
if errorlevel 1 set "PASS=0"

echo.
if "!PASS!"=="1" (
  echo ========  FULL-ZIP EXTRACTION TEST: PASSED  ========
  rd /s /q "%TESTROOT%" >nul 2>&1
  exit /b 0
)
echo ========  FULL-ZIP EXTRACTION TEST: FAILED  ========
echo   Test folder kept for debugging: %TESTROOT%
exit /b 1
EOF_ZIP_TEST_BAT

# --- selfhost_test.bat ---
cat > "$TARGET/selfhost_test.bat" <<'EOF_SELFHOST_TEST_BAT'
@echo off
setlocal enableDelayedExpansion
title Local Search Dev Rig - Self-hosting test (Windows)
REM ===========================================================================
REM  Self-hosting test for the rig packers on Windows (analog of
REM  selfhost_test.sh):
REM    1. Run local-search-rig.bat from a clean folder where it is the ONLY file,
REM       piping scripted answers into it (from a console left on code page
REM       65001, where set /p ignores piped answers unless the packer switches
REM       code pages first).
REM    2. Verify every file the packer embeds is byte-identical after unpacking.
REM    3. Regenerate the packers inside the unpacked rig (gen_rig.py) and compare
REM       them BYTE-FOR-BYTE with the originals.
REM    4. Regenerate the installers too and compare.
REM    5. Run test_rig.py inside the unpacked rig.
REM  The unpack takes a while: the packer writes ~1.5 MB of base64 line by line.
REM ===========================================================================

cd /d "%~dp0"
set "ROOT=%CD%"

set "PY="
py -3 -c "print(1)" >nul 2>&1
if not errorlevel 1 set "PY=py -3"
if not defined PY (
  python -c "print(1)" >nul 2>&1
  if not errorlevel 1 set "PY=python"
)
if not defined PY (
  python3 -c "print(1)" >nul 2>&1
  if not errorlevel 1 set "PY=python3"
)
if not defined PY (
  echo [ERROR] Python not found ^(py / python / python3^).
  exit /b 1
)

if not exist "%ROOT%\local-search-rig.bat" (
  echo [ERROR] local-search-rig.bat not found - run build.bat or python gen_rig.py first.
  exit /b 1
)

set "TESTROOT=%ROOT%\.rig-test-%RANDOM%"
set "SRC=%TESTROOT%\src"
set "RIG=%TESTROOT%\rig"
mkdir "%SRC%" >nul 2>&1
set "PASS=1"

echo === 1. unpack local-search-rig.bat ^(only the packer file present^) ===
copy /Y "%ROOT%\local-search-rig.bat" "%SRC%\" >nul
REM   answers in order: target folder, build now? n (we build manually below), proceed? y
(
  echo !RIG!
  echo n
  echo y
) > "%TESTROOT%\answers.txt"
chcp 65001 >nul
call "%SRC%\local-search-rig.bat" < "%TESTROOT%\answers.txt" > "%TESTROOT%\unpack.log" 2>&1
set "RC=!errorlevel!"
cd /d "%ROOT%"
echo   packer exit code: !RC!
type "%TESTROOT%\unpack.log"
if not "!RC!"=="0" (
  echo   [FAIL] packer exited with !RC!
  goto :failed
)
if not exist "!RIG!\gen_rig.py" (
  echo   [FAIL] the answers were not honoured: nothing was unpacked into the requested folder.
  echo          ^(a packer that ignores piped stdin falls back to its default folder^)
  goto :failed
)
echo.

echo === 2. byte-compare the unpacked rig against the source rig ===
%PY% "%ROOT%\e2e_check.py" rig-compare --src "%ROOT%" --unpacked "!RIG!"
if errorlevel 1 set "PASS=0"
%PY% "%ROOT%\e2e_check.py" same "%ROOT%\local-search-rig.bat" "!RIG!\local-search-rig.bat"
if errorlevel 1 set "PASS=0"
echo.

echo === 3. SELF-HOSTING: regenerate the packers inside the unpacked rig ===
pushd "!RIG!"
%PY% gen_rig.py
if errorlevel 1 (
  echo   [FAIL] gen_rig.py failed in the unpacked rig
  set "PASS=0"
) else (
  %PY% "%ROOT%\e2e_check.py" same "%ROOT%\local-search-rig.bat" "!RIG!\local-search-rig.bat"
  if errorlevel 1 set "PASS=0"
  %PY% "%ROOT%\e2e_check.py" same "%ROOT%\local-search-rig.sh" "!RIG!\local-search-rig.sh"
  if errorlevel 1 set "PASS=0"
)
echo.

echo === 4. regenerate the installers inside the unpacked rig ===
%PY% gen_installers.py
if errorlevel 1 (
  echo   [FAIL] gen_installers.py failed in the unpacked rig
  set "PASS=0"
) else (
  %PY% "%ROOT%\e2e_check.py" same "%ROOT%\local-search\install-local-search.bat" "!RIG!\local-search\install-local-search.bat"
  if errorlevel 1 set "PASS=0"
  %PY% "%ROOT%\e2e_check.py" same "%ROOT%\local-search\install-local-search.sh" "!RIG!\local-search\install-local-search.sh"
  if errorlevel 1 set "PASS=0"
)
echo.

echo === 5. test_rig.py inside the unpacked rig ===
%PY% test_rig.py >nul 2>&1
if errorlevel 1 (
  echo   [FAIL] test_rig.py fails in the unpacked rig
  set "PASS=0"
) else (
  echo   [OK]   test_rig.py passes in the unpacked rig
)
popd
echo.

if "!PASS!"=="1" (
  echo =================  SELF-HOSTING TEST: PASSED  =================
  cd /d "%ROOT%"
  rd /s /q "%TESTROOT%" >nul 2>&1
  exit /b 0
)

:failed
cd /d "%ROOT%"
echo =================  SELF-HOSTING TEST: FAILED  =================
echo   Test folder kept for debugging: %TESTROOT%
exit /b 1
EOF_SELFHOST_TEST_BAT

# --- e2e_check.py ---
cat > "$TARGET/e2e_check.py" <<'EOF_E2E_CHECK_PY'
#!/usr/bin/env python3
"""Assertion helper for the end-to-end install tests (used by e2e_test.bat).

The Windows drivers (e2e_test.bat, zip_test.bat, selfhost_test.bat) only do what
batch is good at - compile the mock docker.exe, pipe scripted answers into the
real installers, run them - and call this script for every assertion, so the
checks are identical on Windows, Linux and macOS and never depend on cmd
quoting rules.

Sub-commands (exit code 0 = all checks passed, 1 = at least one failed):

  install   --target T --home H --mode core|account --searxng-port N
            --firecrawl-port N [--platform windows|posix] [--profile P]
            [--api-key K] [--llm yes|no] [--llm-url U] [--llm-key K]
            [--llm-model M]
  uninstall --target T --home H --folder kept|removed
  docker-log FILE "compose pull" "compose up -d" ...    (substrings, each must appear)
  same      A B                                          (byte-identical files)
  rig-compare --src DIR --unpacked DIR   every file the packers embed (per gen_rig.py)
            is byte-identical in the unpacked rig
"""
import argparse
import os
import re
import sys

OK, FAIL = "  [OK]   ", "  [FAIL] "
failures = 0


def ok(msg):
    print(OK + msg)


def fail(msg):
    global failures
    failures += 1
    print(FAIL + msg)


def check(cond, good, bad):
    ok(good) if cond else fail(bad)
    return bool(cond)


def read(path):
    with open(path, "rb") as f:
        return f.read()


def text(path):
    return read(path).decode("utf-8", "replace")


def norm(p):
    return os.path.normcase(os.path.normpath(p.strip()))


SCRIPTS = "local-web-search/scripts/"
COMMON = [
    "docker-compose.yml", ".env.example", ".env", "README.md", "LICENSE",
    ".gitignore", ".gitattributes", "config/searxng/settings.yml",
    "Run.bat", "Stop.bat", "Update.bat", "Uninstall.bat",
    "run.sh", "stop.sh", "update.sh", "uninstall.sh",
    "local-web-search/SKILL.md",
] + [SCRIPTS + n for n in (
    "config.py", "ensure_stack.py", "firecrawl_api.py", "web_search.py",
    "web_scrape.py", "web_youtube_transcript.py",
    "web_map.py", "web_crawl.py", "web_crawl_status.py")]
ACCOUNT_ONLY = [SCRIPTS + n for n in (
    "web_agent.py", "web_agent_status.py", "web_interact.py",
    "web_interact_stop.py", "web_parse.py", "web_monitor_create.py",
    "web_monitor_list.py", "web_monitor_get.py", "web_monitor_update.py",
    "web_monitor_delete.py", "web_monitor_run.py", "web_monitor_checks.py",
    "web_monitor_check.py", "web_research_search.py",
    "web_research_inspect.py", "web_research_related.py",
    "web_research_read.py", "web_github_search.py", "web_developer_search.py")]
LLM_ONLY = [SCRIPTS + "web_extract.py"]
CORE_MARKER = "Tools: search, scrape, map, crawl, crawl status, YouTube transcripts."  # only in SKILL-core.md
LLM_HEADING = "## LLM extraction"


def env_lines(path):
    return [l.rstrip() for l in text(path).splitlines()]


def cmd_install(a):
    t, home = a.target, a.home
    skill = os.path.join(home, ".agents", "skills", "local-web-search")
    print("Checking install in %s (mode=%s, platform=%s)" % (t, a.mode, a.platform))

    # 1. files present + non-empty
    want = list(COMMON) + ["install-local-search.bat"]
    if a.platform == "posix":
        want.append("install-local-search.sh")
    if a.mode == "account":
        want += ACCOUNT_ONLY
    if a.llm == "yes":
        want += LLM_ONLY
    for rel in want:
        p = os.path.join(t, *rel.split("/"))
        if os.path.isfile(p) and os.path.getsize(p) > 0:
            ok("%s (%d bytes)" % (rel, os.path.getsize(p)))
        else:
            fail("%s missing or empty" % rel)

    # 2. account-gated scripts absent in core mode; build-time variants never left behind
    if a.mode == "core":
        for rel in ACCOUNT_ONLY:
            check(not os.path.exists(os.path.join(t, *rel.split("/"))),
                  "%s absent (core-only install)" % rel,
                  "%s must NOT be installed without a Firecrawl account" % rel)
    if a.llm == "no":
        for rel in LLM_ONLY:
            check(not os.path.exists(os.path.join(t, *rel.split("/"))),
                  "%s absent (no LLM connected)" % rel,
                  "%s must NOT be installed without an LLM" % rel)
    for frag in ("SKILL-core.md", "SKILL-llm.md"):
        check(not os.path.exists(os.path.join(t, "local-web-search", frag)),
              "%s not left in the install folder" % frag,
              "%s leaked into the install folder" % frag)

    # 3. SKILL.md variant
    sk = text(os.path.join(t, "local-web-search", "SKILL.md"))
    if a.mode == "core":
        check(CORE_MARKER in sk and "web_monitor_create" not in sk
              and "web_developer_search" not in sk,
              "SKILL.md is the core-only variant",
              "SKILL.md is not the core-only variant")
    else:
        check("web_monitor_create" in sk and CORE_MARKER not in sk,
              "SKILL.md is the full (account) variant",
              "SKILL.md is not the full variant in account mode")

    check((LLM_HEADING in sk) == (a.llm == "yes"),
          "SKILL.md %s the LLM extraction section" % ("has" if a.llm == "yes" else "omits"),
          "SKILL.md LLM extraction section is %s but --llm is %s"
          % ("present" if LLM_HEADING in sk else "missing", a.llm))

    # 4. .env: the answers that were piped in must have been honoured
    envp = os.path.join(t, ".env")
    lines = env_lines(envp)
    check("SEARXNG_PORT=%s" % a.searxng_port in lines,
          ".env SEARXNG_PORT=%s (scripted answer honoured)" % a.searxng_port,
          ".env SEARXNG_PORT is not %s -> scripted answer was IGNORED. Lines: %s"
          % (a.searxng_port, [l for l in lines if l.startswith("SEARXNG_PORT")]))
    check("FIRECRAWL_PORT=%s" % a.firecrawl_port in lines,
          ".env FIRECRAWL_PORT=%s (scripted answer honoured)" % a.firecrawl_port,
          ".env FIRECRAWL_PORT is not %s -> scripted answer was IGNORED. Lines: %s"
          % (a.firecrawl_port, [l for l in lines if l.startswith("FIRECRAWL_PORT")]))
    check(any(re.fullmatch(r"SEARXNG_SECRET=[0-9a-f]{64}", l) for l in lines),
          ".env has a 64-hex SEARXNG_SECRET",
          ".env SEARXNG_SECRET missing / not 64 hex chars")
    check("COMPOSE_PROFILES=%s" % a.profile in lines,
          ".env COMPOSE_PROFILES=%s" % a.profile,
          ".env COMPOSE_PROFILES is not %s" % a.profile)
    if a.mode == "account":
        check("FIRECRAWL_API_URL=https://api.firecrawl.dev" in lines
              and "FIRECRAWL_API_KEY=%s" % a.api_key in lines,
              ".env holds the Firecrawl account credentials",
              ".env is missing the Firecrawl account credentials")
    else:
        check(not any(l.startswith(("FIRECRAWL_API_KEY=", "FIRECRAWL_API_URL=")) for l in lines),
              ".env has no Firecrawl account credentials (core mode)",
              ".env must not contain account credentials in core mode")

    if a.llm == "yes":
        check("OPENAI_BASE_URL=%s" % a.llm_url in lines
              and "OPENAI_API_KEY=%s" % a.llm_key in lines,
              ".env holds the LLM endpoint (%s)" % a.llm_url,
              ".env LLM settings wrong. Lines: %s" % [l for l in lines if l.startswith(("OPENAI_", "MODEL_NAME"))])
        check(("MODEL_NAME=%s" % a.llm_model in lines) if a.llm_model
              else not any(l.startswith("MODEL_NAME=") for l in lines),
              ".env MODEL_NAME %s" % (a.llm_model or "not set (skipped)"),
              ".env MODEL_NAME wrong. Lines: %s" % [l for l in lines if l.startswith("MODEL_NAME")])
    else:
        check(not any(l.startswith(("OPENAI_BASE_URL=", "OPENAI_API_KEY=", "MODEL_NAME=")) for l in lines),
              ".env has no LLM settings",
              ".env must not contain LLM settings when no LLM is connected")

    st = text(os.path.join(t, "config", "searxng", "settings.yml"))
    check("__SEARXNG_SECRET_PLACEHOLDER__" not in st,
          "settings.yml secret injected (no placeholder left)",
          "settings.yml still contains the secret placeholder")

    # 5. .bat files keep CRLF
    for rel in ("Run.bat", "Stop.bat", "Update.bat", "Uninstall.bat", "install-local-search.bat"):
        b = read(os.path.join(t, rel))
        check(b.count(b"\r\n") > 0 and b.count(b"\n") == b.count(b"\r\n"),
              "%s has CRLF line endings only" % rel,
              "%s has missing/mixed line endings" % rel)

    # 6. skill installed in <home>/.agents/skills, identical to the bundled copy
    check(os.path.isdir(skill), "skill dir exists: %s" % skill, "skill dir missing: %s" % skill)
    skill_files = ["SKILL.md"] + [r[len("local-web-search/"):] for r in COMMON if r.startswith(SCRIPTS)]
    if a.mode == "account":
        skill_files += [r[len("local-web-search/"):] for r in ACCOUNT_ONLY]
    if a.llm == "yes":
        skill_files += [r[len("local-web-search/"):] for r in LLM_ONLY]
    for rel in skill_files:
        sp, bp = (os.path.join(skill, *rel.split("/")),
                  os.path.join(t, "local-web-search", *rel.split("/")))
        if not os.path.isfile(sp):
            fail("skill file missing: %s" % rel)
        elif read(sp) != read(bp):
            fail("skill file differs from bundled copy: %s" % rel)
    ok("skill files present and identical to the bundled copies (%d checked)" % len(skill_files))
    if a.mode == "core":
        leaked = [r for r in ACCOUNT_ONLY if os.path.exists(os.path.join(skill, *r[len("local-web-search/"):].split("/")))]
        check(not leaked, "no account-gated scripts in the installed skill",
              "account-gated scripts leaked into the skill: %s" % leaked)
    if a.llm == "no":
        leaked = [r for r in LLM_ONLY if os.path.exists(os.path.join(skill, *r[len("local-web-search/"):].split("/")))]
        check(not leaked, "no LLM scripts in the installed skill",
              "LLM scripts leaked into the installed skill: %s" % leaked)
    for frag in ("SKILL-core.md", "SKILL-llm.md"):
        check(not os.path.exists(os.path.join(skill, frag)),
              "%s not present in the installed skill" % frag,
              "%s leaked into the installed skill" % frag)
    for d in (skill, os.path.join(t, "local-web-search")):
        hint = os.path.join(d, "install-dir.txt")
        check(os.path.isfile(hint) and norm(text(hint)) == norm(t),
              "install-dir.txt -> %s" % t,
              "install-dir.txt wrong in %s: %r" % (d, text(hint) if os.path.isfile(hint) else None))

    # 7. the skill's own code must resolve the install through the hint + .env
    os.environ["HOME"] = os.environ["USERPROFILE"] = home
    for v in ("LOCAL_SEARCH_DIR", "FIRECRAWL_API_URL", "FIRECRAWL_API_KEY"):
        os.environ.pop(v, None)
    sys.path.insert(0, os.path.join(skill, "scripts"))
    try:
        import config
        import firecrawl_api as fc
        found = config.find_install_dir()
        check(found and norm(found) == norm(t),
              "config.find_install_dir() -> %s" % found,
              "config.find_install_dir() -> %r (expected %r)" % (found, t))
        eps = config.endpoints(found)
        exp = {"searxng": "http://localhost:%s" % a.searxng_port,
               "firecrawl": "http://localhost:%s" % a.firecrawl_port}
        check(eps == exp, "endpoints read from .env: %s" % eps,
              "endpoints wrong: %s (expected %s)" % (eps, exp))
        if a.mode == "account":
            check(fc.base_url() == "https://api.firecrawl.dev" and not fc.is_local()
                  and fc.auth_headers().get("Authorization") == "Bearer %s" % a.api_key,
                  "firecrawl_api routes to the cloud API with the Bearer key",
                  "firecrawl_api did not pick up the account credentials")
        else:
            check(fc.base_url().endswith(":%s" % a.firecrawl_port) and fc.is_local()
                  and fc.auth_headers().get("Authorization") is None,
                  "firecrawl_api routes to the local stack (no Bearer key)",
                  "firecrawl_api local routing wrong: %s" % fc.base_url())
    except Exception as e:                                   # noqa: BLE001
        fail("importing the installed skill failed: %r" % (e,))
    return failures


def cmd_uninstall(a):
    skill = os.path.join(a.home, ".agents", "skills", "local-web-search")
    check(not os.path.exists(skill), "uninstaller removed the skill dir",
          "skill dir still exists after uninstall: %s" % skill)
    kept = os.path.isfile(os.path.join(a.target, ".env")) and \
        os.path.isdir(os.path.join(a.target, "local-web-search"))
    if a.folder == "kept":
        check(kept, "install folder kept (answered 'n' to delete)",
              "install folder was deleted despite answering 'n'")
    else:
        # The running Uninstall.bat itself may stay locked on Windows while it
        # deletes its own folder, so assert the payload is gone, not the dir.
        check(not os.path.exists(os.path.join(a.target, ".env"))
              and not os.path.exists(os.path.join(a.target, "docker-compose.yml")),
              "install folder contents deleted (answered 'y')",
              "install folder contents still exist despite answering 'y': %s" % a.target)
    return failures


def cmd_docker_log(a):
    log = text(a.file) if os.path.isfile(a.file) else ""
    for s in a.expect:
        check(s in log, "docker was called with: %s" % s,
              "docker was never called with: %s (log: %r)" % (s, log[-300:]))
    return failures


def cmd_same(a):
    check(read(a.a) == read(a.b), "identical: %s" % os.path.basename(a.b),
          "DIFFERENT: %s  vs  %s" % (a.a, a.b))
    return failures


def cmd_rig_compare(a):
    sys.path.insert(0, a.src)
    import gen_rig
    n = 0
    for base, names in (("local-search", gen_rig.SOURCE_FILES), ("", gen_rig.RIG_FILES)):
        for rel in names:
            parts = ([base] if base else []) + rel.split("/")
            pa, pb = os.path.join(a.src, *parts), os.path.join(a.unpacked, *parts)
            if not os.path.isfile(pb):
                fail("missing in unpacked rig: %s" % "/".join(parts))
            elif read(pa) != read(pb):
                fail("differs from source: %s" % "/".join(parts))
            else:
                n += 1
    ok("%d files byte-identical between the source rig and the unpacked rig" % n)
    return failures


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("install")
    p.add_argument("--target", required=True); p.add_argument("--home", required=True)
    p.add_argument("--mode", choices=("core", "account"), default="core")
    p.add_argument("--platform", choices=("windows", "posix"), default="windows")
    p.add_argument("--searxng-port", default="9990"); p.add_argument("--firecrawl-port", default="9991")
    p.add_argument("--profile", default="playwright"); p.add_argument("--api-key", default="")
    p.add_argument("--llm", choices=("yes", "no"), default="no")
    p.add_argument("--llm-url", default="http://host.docker.internal:1234/v1")
    p.add_argument("--llm-key", default="placeholder"); p.add_argument("--llm-model", default="")
    p.set_defaults(fn=cmd_install)
    p = sub.add_parser("uninstall")
    p.add_argument("--target", required=True); p.add_argument("--home", required=True)
    p.add_argument("--folder", choices=("kept", "removed"), required=True)
    p.set_defaults(fn=cmd_uninstall)
    p = sub.add_parser("docker-log"); p.add_argument("file"); p.add_argument("expect", nargs="+")
    p.set_defaults(fn=cmd_docker_log)
    p = sub.add_parser("same"); p.add_argument("a"); p.add_argument("b")
    p.set_defaults(fn=cmd_same)
    p = sub.add_parser("rig-compare")
    p.add_argument("--src", required=True); p.add_argument("--unpacked", required=True)
    p.set_defaults(fn=cmd_rig_compare)
    a = ap.parse_args()
    a.fn(a)
    print("  => %s" % ("ALL CHECKS PASSED" if not failures else "%d CHECK(S) FAILED" % failures))
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())
EOF_E2E_CHECK_PY

# --- mock_docker.cs ---
cat > "$TARGET/mock_docker.cs" <<'EOF_MOCK_DOCKER_CS'
// Mock docker.exe for the Windows end-to-end tests (e2e_test.bat).
//
// The installers call "docker compose pull" / "docker compose up -d" directly,
// and a docker.cmd/.bat mock cannot be used for that: batch-to-batch calls
// without CALL never return to the caller. So the tests compile this file into
// a real docker.exe (with the csc.exe that ships with Windows / .NET Framework 4)
// and put it first on PATH.
//
// Behaviour: "info" and everything else succeed; "compose version" prints a
// version line. Every invocation's arguments are appended to the file named by
// the MOCK_DOCKER_LOG environment variable so tests can assert what was run.
using System;
using System.IO;

public static class MockDocker
{
    public static int Main(string[] args)
    {
        string line = String.Join(" ", args);
        string log = Environment.GetEnvironmentVariable("MOCK_DOCKER_LOG");
        if (!String.IsNullOrEmpty(log))
        {
            try { File.AppendAllText(log, line + "\r\n"); } catch (Exception) { }
        }
        if (args.Length >= 1 && args[0] == "info")
        {
            return 0;
        }
        if (args.Length >= 2 && args[0] == "compose" && args[1] == "version")
        {
            Console.WriteLine("Docker Compose version v2.0.0-test");
            return 0;
        }
        Console.WriteLine("[mock] docker " + line);
        return 0;
    }
}
EOF_MOCK_DOCKER_CS

# --- mock_docker_build.bat ---
cat > "$TARGET/mock_docker_build.bat" <<'EOF_MOCK_DOCKER_BUILD_BAT'
@echo off
REM ===========================================================================
REM  Compile the mock docker.exe used by the Windows end-to-end tests.
REM  usage: mock_docker_build.bat OUTPUT-DIR
REM  Uses the csc.exe that ships with .NET Framework 4 (present on Windows
REM  10/11). Exit code 0 means OUTPUT-DIR\docker.exe exists.
REM ===========================================================================
setlocal

if "%~1"=="" (
  echo usage: mock_docker_build.bat ^<output-dir^>
  exit /b 2
)
if not exist "%~1" mkdir "%~1"

set "CSC="
for %%D in ("%SystemRoot%\Microsoft.NET\Framework64\v4.0.30319" "%SystemRoot%\Microsoft.NET\Framework\v4.0.30319") do (
  if not defined CSC if exist "%%~D\csc.exe" set "CSC=%%~D\csc.exe"
)
if not defined CSC (
  echo [ERROR] csc.exe ^(.NET Framework 4 C# compiler^) not found under %SystemRoot%\Microsoft.NET
  exit /b 1
)

"%CSC%" /nologo /target:exe /out:"%~1\docker.exe" "%~dp0mock_docker.cs" > "%~1\csc.log" 2>&1
if errorlevel 1 (
  echo [ERROR] compiling mock_docker.cs failed:
  type "%~1\csc.log"
  exit /b 1
)
if not exist "%~1\docker.exe" (
  echo [ERROR] csc reported success but docker.exe was not produced.
  exit /b 1
)
exit /b 0
EOF_MOCK_DOCKER_BUILD_BAT

# --- build.bat ---
cat > "$TARGET/build.bat" <<'EOF_BUILD_BAT'
@echo off
setlocal enableDelayedExpansion
title Local Search Dev Rig - Build
REM ===========================================================================
REM  Build + test everything in the local-search dev rig on Windows
REM  (analog of build.sh; needs Python 3.8+, nothing else):
REM    1. regenerate the two installers           gen_installers.py
REM    2. verify the embedded files               test_b64.py / test_heredocs.py
REM    3. install / uninstall end-to-end test     e2e_test.bat  (mock docker.exe)
REM    4. regenerate the rig packers + verify     gen_rig.py / test_rig.py
REM    5. self-hosting test                       selfhost_test.bat
REM    6. build local-search.zip                  tar / Compress-Archive
REM    7. zip extraction + install test           zip_test.bat
REM  Set LS_NO_PAUSE=1 to never wait for a key press (automation / CI).
REM  Not run here: e2e_test.sh-only scenarios (Linux docker auto-start through
REM  systemctl, fake-stack self-heal); see BUILD.md.
REM ===========================================================================

cd /d "%~dp0"

set "PY="
py -3 -c "print(1)" >nul 2>&1
if not errorlevel 1 set "PY=py -3"
if not defined PY (
  python -c "print(1)" >nul 2>&1
  if not errorlevel 1 set "PY=python"
)
if not defined PY (
  python3 -c "print(1)" >nul 2>&1
  if not errorlevel 1 set "PY=python3"
)
if not defined PY (
  echo [ERROR] Python not found ^(py / python / python3^). Install Python 3.8+ first.
  call :pause_maybe
  exit /b 1
)

echo == [1/7] Generating installers ==
%PY% gen_installers.py
if errorlevel 1 ( echo [ERROR] gen_installers.py failed. & goto :fail )

echo == [2/7] Embedded-file tests ==
%PY% test_b64.py
if errorlevel 1 ( echo [ERROR] test_b64.py failed. & goto :fail )
%PY% test_heredocs.py
if errorlevel 1 ( echo [ERROR] test_heredocs.py failed. & goto :fail )

echo == [3/7] End-to-end install test ^(mock docker.exe^) ==
call e2e_test.bat
if errorlevel 1 ( echo [ERROR] e2e_test.bat failed. & goto :fail )

echo == [4/7] Regenerating rig packers ==
%PY% gen_rig.py
if errorlevel 1 ( echo [ERROR] gen_rig.py failed. & goto :fail )
%PY% test_rig.py
if errorlevel 1 ( echo [ERROR] test_rig.py failed. & goto :fail )

echo == [5/7] Self-hosting test ==
call selfhost_test.bat
if errorlevel 1 ( echo [ERROR] selfhost_test.bat failed. & goto :fail )

echo == [6/7] Building local-search.zip ==
if exist local-search.zip del local-search.zip
tar -a -c -f local-search.zip local-search >nul 2>&1
if not exist local-search.zip (
  powershell -NoProfile -Command "Compress-Archive -Path 'local-search' -DestinationPath 'local-search.zip'" >nul 2>&1
)
if not exist local-search.zip (
  echo   [WARNING] could not build local-search.zip ^(no tar / Compress-Archive^) - skipping the zip test.
  goto :done
)
echo   local-search.zip built.

echo == [7/7] Zip extraction test ==
call zip_test.bat
if errorlevel 1 ( echo [ERROR] zip_test.bat failed. & goto :fail )

:done
echo.
echo ALL GREEN. Artifacts:
echo   local-search\install-local-search.bat / .sh     the installers
echo   local-search-rig.bat / local-search-rig.sh      the dev-rig packers
echo   local-search.zip                                repo snapshot
echo.
call :pause_maybe
exit /b 0

:fail
echo.
echo BUILD FAILED - see the messages above.
call :pause_maybe
exit /b 1

:pause_maybe
if not defined LS_NO_PAUSE pause
goto :eof
EOF_BUILD_BAT

# --- BUILD.md ---
cat > "$TARGET/BUILD.md" <<'EOF_BUILD_MD'
# 🔧 Local Search — developer rig

This folder is the complete build + test environment for the
**local-search** installers. Everything regenerates from here.

## Layout

```
local-search/                  the product (source of truth — edit freely)
  install-local-search.bat     ← GENERATED by gen_installers.py — do not edit
  install-local-search.sh      ← GENERATED by gen_installers.py — do not edit
  ...                          ← 44 source files (compose, scripts, skill, docs)
gen_installers.py              reads local-search/ → writes the two installers
gen_rig.py                     reads local-search/ + this rig → writes the two packers
extract-embedded.py            pull all embedded files out of any single .sh artifact
e2e_test.bat / zip_test.bat / selfhost_test.bat
                               Windows analogs of the three shell tests (see "Windows 11" below)
e2e_check.py                   cross-platform assertions used by the .bat tests
mock_docker.cs                 source of the mock docker.exe the .bat tests compile
mock_docker_build.bat          compiles mock_docker.cs with the csc.exe that ships with Windows
test_b64.py                    every file embedded in the .bat installer round-trips
test_heredocs.py               every file embedded in the .sh installer matches
test_rig.py                    both rig packers embed the current files exactly
e2e_test.sh                    install → skill → self-heal → account mode → docker auto-start → uninstall (mocked docker + fake stack)
zip_test.sh                    extract local-search.zip and install from it
selfhost_test.sh               unpack a packer alone → regenerate → byte-compare
build.sh / build.bat           regenerate everything + run all tests + build the zip
BUILD.md                       this file
```

## Quick start

Linux / macOS / Git Bash:

```bash
bash build.sh
```

Windows:

```bat
build.bat
```

`build.sh` runs the full pipeline: generate installers → verify embeds →
e2e install test → regenerate the packers → verify packers → self-hosting
test (unpack a packer alone, regenerate, byte-compare) → build + re-test
the zip. `build.bat` runs the same pipeline natively on Windows 11 using the
`.bat` analogs of the tests (no Git Bash / WSL needed, only Python 3.8+).

## Windows 11: building and testing end to end

```bat
build.bat            REM add  set LS_NO_PAUSE=1  first to never wait for a key
```

| Step | Script |
| --- | --- |
| installers | `python gen_installers.py` |
| embed checks | `test_b64.py`, `test_heredocs.py` |
| install + uninstall e2e | `e2e_test.bat` |
| packers | `python gen_rig.py`, `test_rig.py` |
| unpack a packer alone, regenerate, byte-compare | `selfhost_test.bat` |
| zip + extraction install | `zip_test.bat` |

The Windows tests use a **real compiled `docker.exe` mock** (a `.cmd` mock
cannot work: the installers call `docker ...` without `call`, so a batch mock
would never return). `mock_docker_build.bat` compiles `mock_docker.cs` with the
`csc.exe` that ships with .NET Framework 4 (present on Windows 10/11) and the
tests verify the mock is the *first* `docker` on `PATH` before running anything.
Every test runs with `USERPROFILE` redirected into a throw-away folder, so a
real `%USERPROFILE%\.agents\skills\local-web-search` is never touched.

All prompts are driven by **piping scripted answers into the real scripts**
(`script.bat < answers.txt`), using values that differ from the defaults. That
is the regression test for `set /p` under code page 65001 (below).

Not ported to Windows (Linux-specific mocks in `e2e_test.sh`): the docker
auto-start scenarios that use a mock `systemctl`, and the self-heal scenarios
that run a fake Firecrawl/SearXNG HTTP stack. Run those with `bash e2e_test.sh`
from Git Bash/WSL if you need them.

### Windows gotcha: `set /p` and code page 65001

While the console code page is **65001 (UTF-8)**, cmd's `set /p` returns an
**empty line for redirected / piped stdin**, so `script.bat < answers.txt`
gets no answers and every prompt falls back to its default. Every `.bat` that
has prompts follows this rule (`install-local-search.bat`, `local-search-rig.bat`, `Uninstall.bat`):

1. The prompt phase runs on the console's original code page, or 437 if the
   console is already on 65001 (`chcp` persists after a script ends, so an
   earlier script in the same window can leave it there).
2. `chcp 65001` is switched on only **after the last prompt**, for the output
   phase (docker's Unicode progress glyphs, non-ASCII paths).
3. `Uninstall.bat` asks a second question after doing work, so it switches back
   for that prompt (`LS_PROMPT_CP`).

`Run.bat`, `Stop.bat` and `Update.bat` have no prompts and keep `chcp 65001`
at the top. Trade-off: typing non-ASCII characters into a prompt (e.g. a
Cyrillic target folder) happens on the console's original code page; the default folders
and pasted ASCII paths are unaffected.

## Installer setup types and optional-feature gating

Both installers open with a setup-type menu: **1** Minimal installation
(Enter default; defaults, no questions), **2** Minimal + LLM Extraction
(defaults plus the three LLM questions), **3** Full installation (all six
steps; Step 5 "Connect LLM now?" defaults to no).

Optional features install only when selected, using one mechanism each:

| Feature | Selected by | Removed when not selected | SKILL.md handling |
| --- | --- | --- | --- |
| Account tools (`ACCOUNT_TOOLS`) | Firecrawl API key | the 19 scripts | `SKILL-core.md` replaces `SKILL.md` |
| LLM extraction (`LLM_TOOLS`) | an LLM base URL | `web_extract.py` | `SKILL-llm.md` is appended to `SKILL.md` |

`SKILL-core.md` and `SKILL-llm.md` are build-time files: the installers always
delete them from the install folder. The `SKILL.md` description carries no tool
counts, so it stays accurate for every combination.

## Workflow after editing anything

1. Edit any file under `local-search/` (or any rig script).
2. Run `bash build.sh` (or `build.bat`).
3. Artifacts:
   - `local-search/install-local-search.bat` / `.sh` — the self-contained installers
   - `local-search-rig.bat` / `local-search-rig.sh` — the self-contained dev-rig packers
   - `local-search.zip` — repo snapshot for GitHub

## The packers

`local-search-rig.bat` and `local-search-rig.sh` embed the **entire rig** —
the local-search source tree, every generator/test/build script, this file,
and (in the `.sh`) the `.bat` packer itself. That means **either one file
alone** reproduces the complete dev environment, including both packers:

```bash
chmod +x local-search-rig.sh
./local-search-rig.sh        # asks for a folder, unpacks, optionally builds
```

They are **self-hosting**: after unpacking, `python3 gen_rig.py` regenerates
both packers byte-for-byte (verified by the build pipeline and by
`selfhost_test.sh`, which unpacks a packer into a clean folder and proves
regeneration is exact). The generated installers themselves are NOT embedded —
run the build (the packer offers) or `python3 gen_installers.py` to create
them fresh.

## Manual commands

```bash
python3 gen_installers.py    # rebuild just the two installers
python3 gen_rig.py           # rebuild just the two packers
python3 test_b64.py          # verify .bat installer embeds
python3 test_heredocs.py     # verify .sh installer embeds
python3 test_rig.py          # verify packer embeds
bash e2e_test.sh             # install/uninstall + self-heal test (mocked docker)
bash zip_test.sh             # zip extraction test (needs unzip)
bash selfhost_test.sh        # unpack a packer alone → regenerate → byte-compare
```

## Single-file recovery (no Docker needed)

Lost everything except one `.sh` artifact? `extract-embedded.py` pulls every
embedded file out of it — it only parses the quoted heredocs, nothing is
executed:

```bash
# from the rig packer: recovers the COMPLETE rig (57 files)
python3 extract-embedded.py local-search-rig.sh rig
# then regenerate everything:
cd rig && python3 gen_installers.py && python3 gen_rig.py

# from the installer: recovers the local-search/ sources + the .bat installer
python3 extract-embedded.py install-local-search.sh local-search
# add the rig scripts (visible in the repo) next to it and regenerate.
```

The `.sh` file you extracted from is never embedded in itself — copy it over
manually if you want it in the recovered tree.

## Conventions

- **Line endings:** `.bat` sources are CRLF; `.sh` / `.py` / `.md` / `.yml`
  are LF. The `.sh` packer normalizes to LF inside its heredocs and restores
  CRLF for every `*.bat` on unpack (via awk, so it also works on macOS).
- **bash 3.2 safe:** all shell scripts avoid `${var,,}`, `sed -i`, and
  GNU-only sed escapes, so they run on the macOS default shell. Case-folding
  goes through the `lower()` helper (`tr '[:upper:]' '[:lower:]'`).
- **Safe tests:** `e2e_test.sh` and `zip_test.sh` back up and restore
  `~/.agents/skills/local-web-search` if you have a real install — they never
  destroy it. Test folders (`.ls-test-*`, `.zip-test-*`) are removed on
  success and kept on failure for debugging.
- **Mocked docker:** the e2e tests put a fake `docker` on PATH, so they run
  the full install logic without touching a real Docker daemon.
EOF_BUILD_MD

# --- local-search-rig.bat ---
cat > "$TARGET/local-search-rig.bat" <<'EOF_LOCAL_SEARCH_RIG_BAT'
@echo off
setlocal enableDelayedExpansion
title Local Search Dev Rig - Unpack
REM  Prompts run on a code page other than 65001: while the console is on 65001
REM  (UTF-8), set /p returns an empty line for redirected or piped stdin, so
REM  scripted answers are lost. The code page the console started on is used, or
REM  437 when it is already 65001 (chcp persists after a script ends). UTF-8 is
REM  enabled after the last prompt.
set "LS_PROMPT_CP=437"
for /f "tokens=2 delims=:" %%c in ('chcp') do for /f %%n in ("%%c") do set "LS_PROMPT_CP=%%n"
if "!LS_PROMPT_CP!"=="65001" set "LS_PROMPT_CP=437"
chcp !LS_PROMPT_CP! >nul 2>&1

REM ===========================================================================
REM  Local Search DEV RIG packer  -  Windows
REM ===========================================================================
REM  Self-contained: embeds the complete build/test environment for the
REM  local-search installers:
REM    * the local-search source tree (47 files)
REM    * gen_installers.py / gen_rig.py (the two generators)
REM    * every test + build script + BUILD.md
REM  Unpack anywhere, then run build.bat (or: python gen_installers.py) to
REM  regenerate the installers, and: python gen_rig.py to regenerate these
REM  packers byte-for-byte.
REM ===========================================================================

